<?php
function recon_review_batch($id,$lock=false){$q=db()->prepare('SELECT * FROM process_reconciliations WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$b=$q->fetch();if(!$b)throw new Exception('Reconciliation upload not found.');return $b;}
function recon_stage($file){validate_upload_file($file,['xlsx']);$rows=XlsxReader::rows($file['tmp_name']);$hr=find_header_row($rows,[['item','quantity'],['item','on hand'],['description','quantity'],['name','quantity'],['SKU','quantity']]);if($hr===null)throw new Exception('Use Item / SKU / Description and Quantity / On Hand columns.');$h=array_map('norm',$rows[$hr]);$ix=function($names)use($h){foreach($names as $n){$i=array_search($n,$h,true);if($i!==false)return $i;}return null;};$ii=$ix(['item','description','name','sku']);$qi=$ix(['on hand','quantity','qty','available']);$items=[];foreach(array_slice($rows,$hr+1) as $i=>$r){if(!array_filter($r,fn($v)=>trim((string)$v)!==''))continue;$item=trim($r[$ii]??'');$items[]=['row'=>$hr+$i+2,'item'=>$item,'product_id'=>return_match($item),'qty'=>trim($r[$qi]??''),'remarks'=>''];}if(!$items)throw new Exception('No reconciliation rows found.');$stored=store_upload($file,'reconciliation','RECON');db()->prepare('INSERT INTO process_reconciliations(filename,stored_path,rows_json,created_by) VALUES(?,?,?,?)')->execute([basename($file['name']),$stored,json_encode($items),current_user()['id']]);$id=(int)db()->lastInsertId();audit('Review reconciliation','Reconciliation',(string)$id,'All '.count($items).' source rows retained; no inventory changes.');return $id;}
function recon_analysis($b){$rows=json_decode($b['rows_json'],true)?:[];$errors=[];$seen=[];foreach($rows as &$r){$r['error']='';try{$p=active_product((int)$r['product_id']);$r['name']=$p['name'];$r['sku']=$p['master_sku'];if(!preg_match('/^-?\d+$/D',(string)$r['qty'])||abs((int)$r['qty'])>100000000)throw new Exception('Quantity must be a whole number.');if(isset($seen[$p['id']]))throw new Exception('Repeated product. Consolidate its source quantity before submission.');$seen[$p['id']]=true;$s=stock_row($p['id']);if($b['status']==='Review'){$r['sellable']=$s['current'];$r['damaged']=$s['nonsellable'];$r['physical']=$s['physical'];$r['variance']=(int)$r['qty']-$s['physical'];}}catch(Throwable $e){$r['error']=$e->getMessage();$errors[]='Row '.$r['row'].': '.$r['error'];}}unset($r);return ['rows'=>$rows,'errors'=>$errors,'digest'=>hash('sha256',json_encode([$b['revision'],$rows]))];}
function recon_correct($id,$row,$revision,$input){return process_transaction(function()use($id,$row,$revision,$input){$b=recon_review_batch($id,true);if($b['status']!=='Review'||(int)$b['revision']!==(int)$revision)throw new Exception('Review changed. Refresh first.');$rows=json_decode($b['rows_json'],true);$found=false;foreach($rows as &$r)if((int)$r['row']===(int)$row){$r['product_id']=(int)($input['product_id']??0);$r['qty']=$input['qty']??'';$r['remarks']=trim($input['remarks']??'');$found=true;break;}unset($r);if(!$found)throw new Exception('Row not found.');db()->prepare('UPDATE process_reconciliations SET rows_json=?,revision=revision+1 WHERE id=?')->execute([json_encode($rows),$id]);audit('Correct reconciliation','Reconciliation',(string)$id,'Row '.$row.'; inventory unchanged.');});}
function recon_confirm($id,$digest,$ack){if(!$ack)throw new Exception('Confirm the reviewed comparison.');return process_transaction(function()use($id,$digest){$b=recon_review_batch($id,true);if($b['status']!=='Review')throw new Exception('Already posted or cancelled.');$a=recon_analysis($b);if($a['errors'])throw new Exception('Resolve every row before submitting.');if(!hash_equals($a['digest'],$digest))throw new Exception('Review or stock changed. Refresh final confirmation.');db()->prepare('INSERT INTO reconciliation_batches(filename,user_id) VALUES(?,?)')->execute([$b['filename'],current_user()['id']]);$legacy=(int)db()->lastInsertId();$q=db()->prepare('INSERT INTO reconciliations(batch_id,product_id,netsuite_qty,internal_sellable,nonsellable,physical_total,variance) VALUES(?,?,?,?,?,?,?)');foreach($a['rows'] as $r)$q->execute([$legacy,$r['product_id'],(int)$r['qty'],$r['sellable'],$r['damaged'],$r['physical'],$r['variance']]);db()->prepare("UPDATE process_reconciliations SET status='Posted',rows_json=?,posted_by=?,legacy_batch_id=? WHERE id=?")->execute([json_encode($a['rows']),current_user()['id'],$legacy,$id]);audit('Post reconciliation comparison','Reconciliation',(string)$id,count($a['rows']).' rows; comparison only, no stock adjustment.');return $legacy;});}
function recon_cancel($id){process_transaction(function()use($id){$b=recon_review_batch($id,true);if($b['status']!=='Review')throw new Exception('Only pending uploads can be cancelled.');db()->prepare("UPDATE process_reconciliations SET status='Cancelled' WHERE id=?")->execute([$id]);audit('Cancel reconciliation','Reconciliation',(string)$id,'Inventory unchanged.');});}
